js=S_JS + r'''
function calc(){
var v1=P('v1'),v2=P('v2'),r1=P('r1'),r2=P('r2'),r3=P('r3'),r4=P('r4');
if([v1,v2,r1,r2,r3,r4].some(isNaN))return err('Заполните числами V1, V2 и сопротивления R1–R4.');
if(r1<=0||r2<=0||r3<=0||r4<=0)return err('Сопротивления R1–R4 должны быть больше нуля.');
var vr=OPT('vref'),t=OPT('tol'),s1=OPT('rs1'),s2=OPT('rs2'),lo=OPT('vomin'),hi=OPT('vomax'),cl=OPT('vcmmin'),ch=OPT('vcmmax');
if(vr!==null&&isNaN(vr))return err('Vref — число в вольтах. Если R4 подключён к общему проводу, оставьте поле пустым.');
if(t!==null){if(isNaN(t))return err('Допуск резисторов — число в процентах. Если он неизвестен, оставьте поле пустым.');if(!(t>0&&t<20))return err('Допуск резисторов — больше 0 и меньше 20 %.');}
if(s1!==null){if(isNaN(s1))return err('Выходное сопротивление источника V1 — число. Если оно пренебрежимо мало, оставьте поле пустым.');if(s1<0)return err('Выходное сопротивление источника V1 не может быть отрицательным.');}
if(s2!==null){if(isNaN(s2))return err('Выходное сопротивление источника V2 — число. Если оно пренебрежимо мало, оставьте поле пустым.');if(s2<0)return err('Выходное сопротивление источника V2 не может быть отрицательным.');}
if((lo===null)!==(hi===null))return err('Задайте обе границы выхода ОУ или оставьте обе пустыми.');
if(lo!==null){if(isNaN(lo)||isNaN(hi))return err('Границы выхода ОУ — числа в вольтах.');if(!(lo<hi))return err('Нижняя граница выхода ОУ должна быть меньше верхней.');}
if((cl===null)!==(ch===null))return err('Задайте обе границы синфазного напряжения ОУ или оставьте обе пустыми.');
if(cl!==null){if(isNaN(cl)||isNaN(ch))return err('Границы синфазного напряжения ОУ — числа в вольтах.');if(!(cl<ch))return err('Нижняя граница синфазного напряжения должна быть меньше верхней.');}
var V=vr===null?0:vr,a=s1===null?0:s1,b=s2===null?0:s2;
// Идеальный ОУ: V+ — делитель R3–R4 между V2 и Vref; ток R1 равен току R2 (правило узлов).
// Сопротивления источников прибавляются к R1 и R3. D = 0 — точное равенство R2/R1 = R4/R3.
function ev(x1,x2,x3,x4){var R1=x1+a,R3=x3+b,vp=(v2*x4+V*R3)/(R3+x4),g=x2/R1,D=R1*x4-x2*R3,den=R1*(R3+x4);
 return {vp:vp,vo:vp*(1+g)-v1*g,ad:(x4*(R1+x2)+x2*(R3+x4))/(2*den),acm:D/den,z:Math.abs(D)<=1e-12*R1*x4,R1:R1,R3:R3};}
var e=ev(r1,r2,r3,r4),vd=v2-v1,vc=(v1+v2)/2,k2=r4/(e.R3+r4)*(1+r2/e.R1),kr=e.R3/(e.R3+r4)*(1+r2/e.R1),cm=e.z?Infinity:Math.abs(e.ad/e.acm);
if(![e.vp,e.vo,e.ad].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
var h=row('Напряжение на входах ОУ V+ = '+(vr===null?'V2·R4/(R3 + R4)':'(V2·R4 + Vref·R3)/(R3 + R4)'),fmt(e.vp,4)+' В')+
 row('Выход идеального ОУ Vвых = V+·(1 + R2/R1) − V1·R2/R1',fmt(e.vo,4)+' В')+
 row('Коэффициенты передачи: V2 / V1'+(vr===null?'':' / Vref'),fmt(k2,6)+' / '+fmt(-r2/e.R1,6)+(vr===null?'':' / '+fmt(kr,6)))+
 row('Разностный сигнал V2 − V1 / синфазный (V1 + V2)/2',fmt(vd,4)+' / '+fmt(vc,4)+' В')+
 row('Дифференциальное усиление Aд',fmt(e.ad,6)+' — '+fmt(db(e.ad),4)+' дБ')+
 row('Синфазное усиление Aсф по номиналам',e.z?'0: R2/R1 = R4/R3':fmt(e.acm,4))+
 row('КОСС резисторов по номиналам',e.z?'бесконечен: R2/R1 = R4/R3':fmt(cm,4)+' — '+fmt(db(cm),4)+' дБ');
if(s1!==null||s2!==null)h+=row('С сопротивлениями источников: R1 + Rи1 / R3 + Rи2',si(e.R1,'Ом')+' / '+si(e.R3,'Ом'));
// Наихудший случай: все 16 сочетаний ±t. КОСС = N/(2|D|): N и D линейны по каждому резистору,
// поэтому отношение монотонно по каждому из них и наихудшее значение лежит в углу.
var wn=Infinity,am=0,vo0=Infinity,vo1=-Infinity,vp0=Infinity,vp1=-Infinity;
if(t!==null){var f=t/100;
 for(var k=0;k<16;k++){var q=ev(r1*(1+((k&1)?f:-f)),r2*(1+((k&2)?f:-f)),r3*(1+((k&4)?f:-f)),r4*(1+((k&8)?f:-f)));
  var c=q.z?Infinity:Math.abs(q.ad/q.acm);if(c<wn)wn=c;if(Math.abs(q.acm)>am)am=Math.abs(q.acm);
  vo0=Math.min(vo0,q.vo);vo1=Math.max(vo1,q.vo);vp0=Math.min(vp0,q.vp);vp1=Math.max(vp1,q.vp);}
 var ap=(1+Math.abs(e.ad))/(4*f);
 h+=row('КОСС в наихудшем из 16 сочетаний ±'+fmt(t)+' %',fmt(wn,4)+' — '+fmt(db(wn),4)+' дБ')+
  row('Для сравнения: приближение TI и ADI (1 + Aд)/(4t) — для согласованных номиналов',fmt(ap,4)+' — '+fmt(db(ap),4)+' дБ')+
  row('Наибольшее |Aсф| при допуске',fmt(am,4)+' — ошибка выхода от синфазных '+fmt(vc,4)+' В до ±'+si(am*Math.abs(vc),'В'))+
  row('Выход при допусках резисторов',fmt(vo0,4)+' … '+fmt(vo1,4)+' В')+
  row('Напряжение на входах ОУ при допусках',fmt(vp0,4)+' … '+fmt(vp1,4)+' В');}
h+=row('Входное сопротивление со стороны V2: R3 + R4',si(r3+r4,'Ом'))+
 row('Со стороны V1: R1 — при V+ = 0',si(r1,'Ом'))+
 row('Для плавающего источника между входами: R1 + R3',si(r1+r3,'Ом'))+
 row('Токи входов при этих напряжениях: I1 / I2',si((v1-e.vp)/e.R1,'А')+' / '+si((v2-V)/(e.R3+r4),'А'));
var bad=[],risk=[],miss=[];
function chk(x,x0,x1,l,u,what,tail){
 if(lt(x,l)){bad.push(what+' '+fx(x,l)+' В ниже нижней границы '+fx(l,x)+' В'+tail);return fx(x,l)+' В ниже нижней границы '+fx(l,x)+' В';}
 if(gt(x,u)){bad.push(what+' '+fx(x,u)+' В выше верхней границы '+fx(u,x)+' В'+tail);return fx(x,u)+' В выше верхней границы '+fx(u,x)+' В';}
 if(t!==null){if(lt(x0,l))risk.push('при допусках резисторов '+what+' доходит до '+fx(x0,l)+' В — ниже нижней границы '+fx(l,x0)+' В');
  if(gt(x1,u))risk.push('при допусках резисторов '+what+' доходит до '+fx(x1,u)+' В — выше верхней границы '+fx(u,x1)+' В');}
 return fmt(x,4)+' В в пределах '+fmt(l,4)+' … '+fmt(u,4)+' В';}
if(lo===null)miss.push('границы выхода ОУ');
else h+=row('Выход и границы по паспорту ОУ',chk(e.vo,vo0,vo1,lo,hi,'выход',' — сигнал ограничится'));
if(cl===null)miss.push('синфазный диапазон входов ОУ');
else h+=row('Напряжение на входах ОУ и синфазный диапазон',chk(e.vp,vp0,vp1,cl,ch,'напряжение на входах ОУ',' — ОУ вне своего синфазного диапазона, расчёт для идеального ОУ неприменим'));
if(t===null)miss.push('допуск резисторов');
var st;
if(bad.length)st=cap(bad.join('; '));
else if(risk.length)st='Риск: '+risk.join('; ');
else if(miss.length)st='Недостаточно данных: не заданы '+miss.join(', ')+'; по идеальному ОУ Vвых = '+fmt(e.vo,4)+' В';
else st='Оценка: выход '+fmt(e.vo,4)+' В и напряжение на входах ОУ '+fmt(e.vp,4)+' В в пределах паспорта и при допусках резисторов; наихудший КОСС резисторов '+fmt(db(wn),4)+' дБ';
var n='Расчёт для идеального ОУ: входы не потребляют ток, напряжения входов равны. Собственный КОСС ОУ, смещение нуля, входные токи и конечное усиление не учтены: КОСС схемы не бывает выше КОСС самого ОУ, а на высоких частотах его снижают ещё и ёмкости. ';
n+='Наихудший КОСС — перебор всех 16 сочетаний ±t; приближение (1 + Aд)/(4t) дано для сравнения: TI в SBOA274 берёт α = 4 для наихудшего случая и α = 0,33 для вероятного. ';
n+='Источник V2 нагружен на R3 + R4, источник V1 — на R1 с поправкой на V+: сопротивления источников складываются с R1 и R3 и нарушают равенство отношений.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">V+ = V2·R4/(R3 + R4) + Vref·R3/(R3 + R4)<br>Vвых = V+·(1 + R2/R1) − V1·R2/R1<br>Vвых = Aд·(V2 − V1) + Aсф·(V1 + V2)/2 + Vref·R3·(1 + R2/R1)/(R3 + R4)<br>Aд = [R4·(R1 + R2) + R2·(R3 + R4)] / [2·R1·(R3 + R4)],&nbsp;&nbsp;Aсф = (R1·R4 − R2·R3) / [R1·(R3 + R4)],&nbsp;&nbsp;КОСС = |Aд / Aсф|<br>при R2/R1 = R4/R3: Vвых = (R2/R1)·(V2 − V1) + Vref<br>наихудший КОСС при допуске ±t — перебор 16 сочетаний; для сравнения ≈ (1 + Aд)/(4t)</div>
<p><b>Вывод из суперпозиции.</b> У идеального ОУ входы не потребляют ток, а отрицательная обратная связь через R2 удерживает напряжения обоих входов равными. Неинвертирующий вход подключён к делителю R3–R4 между V2 и Vref, поэтому по правилу узлов (закон токов Кирхгофа) на нём V+ = (V2·R4 + Vref·R3)/(R3 + R4). На инвертирующем входе то же напряжение, и ток через R1 равен току через R2: (V1 − V+)/R1 = (V+ − Vвых)/R2. Отсюда Vвых = V+·(1 + R2/R1) − V1·R2/R1. Это сумма двух известных схем: при V2 = Vref = 0 остаётся инвертирующий усилитель с усилением −R2/R1, при V1 = 0 — делитель и неинвертирующий усилитель 1 + R2/R1. Каждую из них по отдельности считает <a href="ou-usilenie.html">калькулятор операционного усилителя</a>.</p>
<p><b>Дифференциальное и синфазное усиление.</b> Если записать V1 = Vсф − Vд/2 и V2 = Vсф + Vд/2, выход распадается на Aд·Vд и Aсф·Vсф. Синфазное усиление пропорционально разности R1·R4 − R2·R3 и обращается в ноль только при равенстве отношений R2/R1 = R4/R3 — тогда выход зависит лишь от разности входов. Коэффициент ослабления синфазного сигнала (КОСС, CMRR) — отношение |Aд/Aсф|, в децибелах 20·lg. Расчёт идёт для идеального ОУ: собственный КОСС ОУ, смещение нуля и входные токи не учтены, и КОСС схемы не бывает выше КОСС самого ОУ.</p>
<p><b>Допуск резисторов и наихудший случай.</b> Резисторы с допуском ±t почти никогда не дают точного равенства отношений, и КОСС ограничивают именно они, а не ОУ (TI, SBOA274). Калькулятор перебирает все 16 сочетаний «плюс или минус t» для R1–R4 и берёт наихудшее. Перебора углов достаточно: КОСС = N/(2·|D|), где N = R4·(R1 + R2) + R2·(R3 + R4) и D = R1·R4 − R2·R3 линейны по каждому резистору, поэтому отношение монотонно по каждому из них и наихудшее значение лежит в одном из углов. Для сравнения показано приближение (1 + Aд)/(4t): в записи TI CMRR(дБ) ≈ 20·lg[(1 + G)/(α·ε)] коэффициент α = 4 соответствует наихудшему случаю, а α = 0,33 — вероятному значению. Пример ADI (H. Holt, Analog Dialogue): при единичном усилении и резисторах 1 % КОСС 50 — около 34 дБ, при 0,1 % — 500, около 54 дБ. Приближение совпадает с перебором с точностью до t²: при согласованных номиналах точное наихудшее значение (1 + G + t²·(1 − G))/(4t).</p>
<p><b>Входные сопротивления разные.</b> Источник V2 видит R3 + R4 — ток уходит через делитель к Vref. Ток источника V1 равен (V1 − V+)/R1 и зависит от второго входа: при V+ = 0 входное сопротивление равно R1, а для плавающего источника, включённого между входами, — R1 + R3. Kitchin и Counts (ADI) приводят пример: при четырёх резисторах по 100 кОм один вход нагружен на 100 кОм, другой — на 200 кОм. Последствие для источника сигнала: его выходное сопротивление складывается с R1 или R3 и нарушает равенство отношений, а значит, снижает КОСС, — даже 1 кОм на входе с R3 = 10 кОм заметен. Введите выходные сопротивления источников, и калькулятор прибавит их к R1 и R3. Высокоомным источникам нужен буфер или инструментальный усилитель.</p>
<p><b>Опорное напряжение и проверка по паспорту ОУ.</b> Vref сдвигает выход: при равных отношениях Vвых = (R2/R1)·(V2 − V1) + Vref. Источник Vref должен иметь малое выходное сопротивление — оно складывается с R4. Выход идеального ОУ сравнивается с границами, которые вы берёте из паспорта при своих питании и нагрузке, как на странице <a href="ou-usilenie.html">операционного усилителя</a>. Отдельно проверяется напряжение на входах ОУ V+: оно должно лежать в синфазном диапазоне входов ОУ. Делитель R3–R4 делит синфазное напряжение, поэтому схема работает и тогда, когда сами V1 и V2 выходят за этот диапазон. Без паспортных границ калькулятор пишет «Недостаточно данных».</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="ou-usilenie.html">Калькулятор ОУ</a> считает одновходовые инвертирующий и неинвертирующий усилители. Здесь входов два, и главный вопрос — насколько схема подавляет общее для них напряжение. Мостовые датчики, сигнал которых часто снимают таким усилителем, считает <a href="most-uitstona.html">калькулятор моста Уитстона</a>, а делитель на входе — <a href="delitel-napryazheniya.html">калькулятор делителя напряжения</a>.</p>""",
example="""<p>Датчик выдаёт 2,45 и 2,55 В: разность 0,1 В на синфазном уровне 2,5 В. Усилитель с R1 = R3 = 10 кОм и R2 = R4 = 100 кОм: V+ = 2,55·100/110 = 2,318 В, выход идеального ОУ (2,318·11 − 2,45·10) = <b>1 В</b>, Aд = 10 (20 дБ), по номиналам синфазное усиление равно нулю и КОСС бесконечен.</p>
<p>С резисторами 1 % наихудшее из 16 сочетаний даёт КОСС 275 — <b>48,79 дБ</b>, приближение (1 + 10)/(4·0,01) = 275. Синфазное усиление доходит до 0,03703: синфазные 2,5 В дают на выходе ошибку до ±92,58 мВ, и выход лежит между 0,9258 и 1,071 В. С резисторами 0,1 % КОСС — 68,79 дБ, ошибка — до ±9,107 мВ.</p>
<p>Если у источника V2 выходное сопротивление 1 кОм, оно складывается с R3: R3 + Rи2 = 11 кОм, отношения уже не равны, выход 0,7703 В вместо 1 В, а КОСС по номиналам падает до 110,5 — 40,87 дБ. Значения условные; границы выхода и синфазного диапазона введите из паспорта своего ОУ.</p>""",
