 dict(id="c", label="Ёмкость C для синтеза", units=C_UNITS, ui=1, val="10", hint="Единичное усиление: ФНЧ — C2 = C, C1 = 2·C; ФВЧ — C1 = C2 = C. Равные элементы: C1 = C2 = C"),
 dict(id="ras", label="Ra для синтеза с равными элементами", units=R_UNITS, ui=1, val="10", hint="Rb = (2 − √2)·Ra даёт K = 3 − √2"),
 dict(id="tr", label="Допуск резисторов ±", unit="%", val="", hint="Необязательное: по маркировке резисторов. Вместе с допуском конденсаторов даёт разброс f0 и Q и проверку самовозбуждения"),
 dict(id="tc", label="Допуск конденсаторов ±", unit="%", val="", hint="Необязательное: по маркировке конденсаторов"),
 dict(id="gbw", label="Произведение усиления на полосу GBW ОУ", units=F_UNITS, ui=2, val="", hint="Необязательное: по паспорту ОУ"),
 dict(id="sr", label="Скорость нарастания SR ОУ", unit="В/мкс", val="", hint="Необязательное: по паспорту ОУ"),
