js=S_JS + r'''
function sync(){var m=S('mode'),an=m==='an',hp=S('typ')==='hp';
hideF('r1',!an);hideF('r2',!an);hideF('c1',!an);hideF('c2',!an);hideF('rb',!an);hideF('ra',!an);
hideF('f0',an);hideF('c',an);hideF('ras',m!=='se');hideF('fmax',!hp);}
function init(){$('typ').addEventListener('change',sync);$('mode').addEventListener('change',sync);sync();}
// Узловые уравнения: знаменатель s²·R1R2C1C2 + s·d + 1. d — коэффициент при s; Q = √(R1R2C1C2)/d;
// d ≤ 0 — полюса не в левой полуплоскости. x = [R1, R2, C1, C2].
function qv(hp,x,K){var d=hp?x[0]*x[2]+x[0]*x[3]+x[1]*x[3]*(1-K):x[0]*x[3]+x[1]*x[3]+x[0]*x[2]*(1-K);return {d:d,q:Math.sqrt(x[0]*x[1]*x[2]*x[3])/d};}
function calc(){
var hp=S('typ')==='hp',m=S('mode'),R1,R2,C1,C2,K,rb=0,ra=null,syn='';
if(m==='an'){R1=P('r1');R2=P('r2');C1=P('c1');C2=P('c2');rb=P('rb');ra=OPT('ra');
 if([R1,R2,C1,C2,rb].some(isNaN))return err('Заполните числами R1, R2, C1, C2 и Rb (0 — повторитель).');
 if(R1<=0||R2<=0||C1<=0||C2<=0)return err('Сопротивления и ёмкости должны быть больше нуля.');
 if(rb<0)return err('Rb не может быть отрицательным; 0 — повторитель.');
 if(ra!==null&&isNaN(ra))return err('Ra — число. При Rb = 0 оставьте поле пустым.');
 if(rb>0){if(ra===null)return err('При Rb больше нуля задайте Ra: K = 1 + Rb/Ra.');if(ra<=0)return err('Ra должно быть больше нуля.');K=1+rb/ra;}else K=1;}
else{var fs=P('f0'),c=P('c');
 if(isNaN(fs)||isNaN(c))return err('Введите частоту f0 и ёмкость C для синтеза.');
 if(fs<=0||c<=0)return err('Частота и ёмкость должны быть больше нуля.');
 var w=2*Math.PI*fs;
 if(m==='su'){K=1;R1=1/(w*c*Math.SQRT2);C1=hp?c:2*c;C2=c;R2=hp?2*R1:R1;
  syn=row('Рассчитанные элементы: R1 / R2 / C1 / C2',sp(R1,'Ом')+' / '+sp(R2,'Ом')+' / '+sp(C1,'Ф')+' / '+sp(C2,'Ф'));}
 else{ra=P('ras');if(isNaN(ra))return err('Введите Ra для синтеза с равными элементами.');if(ra<=0)return err('Ra должно быть больше нуля.');
  R1=1/(w*c);R2=R1;C1=c;C2=c;rb=(2-Math.SQRT2)*ra;K=1+rb/ra;
  syn=row('Рассчитанные элементы: R1 = R2 / C1 = C2',sp(R1,'Ом')+' / '+sp(c,'Ф'))+row('Резисторы усиления: Rb = (2 − √2)·Ra / Ra',sp(rb,'Ом')+' / '+sp(ra,'Ом'));}}
var tr=OPT('tr'),tc=OPT('tc'),gb=OPT('gbw'),sr=OPT('sr'),vin=OPT('vin'),fm=hp?OPT('fmax'):null;
if(tr!==null){if(isNaN(tr))return err('Допуск резисторов — число в процентах. Если он неизвестен, оставьте поле пустым.');if(!(tr>=0&&tr<20))return err('Допуск резисторов — от 0 до 20 %, не включая 20.');}
if(tc!==null){if(isNaN(tc))return err('Допуск конденсаторов — число в процентах. Если он неизвестен, оставьте поле пустым.');if(!(tc>=0&&tc<50))return err('Допуск конденсаторов — от 0 до 50 %, не включая 50.');}
if(gb!==null){if(isNaN(gb))return err('GBW — число. Если его нет, оставьте поле пустым.');if(gb<=0)return err('GBW должно быть больше нуля.');}
if(sr!==null){if(isNaN(sr))return err('Скорость нарастания — число в В/мкс. Если её нет, оставьте поле пустым.');if(sr<=0)return err('Скорость нарастания должна быть больше нуля.');}
if(vin!==null){if(isNaN(vin))return err('Амплитуда сигнала — число в вольтах. Если она неизвестна, оставьте поле пустым.');if(vin<=0)return err('Амплитуда сигнала должна быть больше нуля.');}
if(fm!==null){if(isNaN(fm))return err('Наибольшая частота сигнала — число. Если она неизвестна, оставьте поле пустым.');if(fm<=0)return err('Наибольшая частота сигнала должна быть больше нуля.');}
var x=[R1,R2,C1,C2],f0=1/(2*Math.PI*Math.sqrt(R1*R2*C1*C2)),e=qv(hp,x,K);
var kl=hp?1+(R1*C1+R1*C2)/(R2*C2):1+(R1*C2+R2*C2)/(R1*C1),eq=R1===R2&&C1===C2;
if(![f0,kl,e.d].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
var h=syn+row('Усиление в полосе пропускания K = 1 + Rb/Ra',fmt(K,4)+' — '+fmt(db(K),4)+' дБ'+(K===1?', повторитель':''))+
 row('Собственная частота f0 = 1/(2π·√(R1·R2·C1·C2))',sp(f0,'Гц'))+
 row('Порог самовозбуждения по усилению Kпред'+(eq?' — при равных элементах 3':''),fx(kl,K)+' при K = '+fx(K,kl));
var n='Формулы f0 и Q выведены из узловых уравнений для идеального ОУ — вывод в статье ниже; TI в SLOA024B разбирает ту же схему и для равных элементов даёт Q = 1/(3 − K). ';
if(ge(K,kl)){
 h+=row('Добротность Q',gt(K,kl)?'отрицательная: полюса в правой полуплоскости':'бесконечная: полюса на мнимой оси');
 var s0=gt(K,kl)?'Фильтр самовозбуждается: K = '+fx(K,kl)+' больше порога '+fx(kl,K)+' — полюса в правой полуплоскости, схема генерирует':'Фильтр на границе самовозбуждения: K = '+fx(K,kl)+' равно порогу — добротность бесконечна, малейший разброс элементов даёт генерацию';
 return out(h+row('Статус',s0+'; уменьшите усиление или измените соотношение элементов')+note(n+'Положительная обратная связь через '+(hp?'R1':'C1')+' с ростом K уменьшает коэффициент при s в знаменателе; при нуле и ниже фильтр превращается в генератор.'));}
var q=e.q,a2=2-1/(q*q),y=(a2+Math.sqrt(a2*a2+4))/2,f3=hp?f0/Math.sqrt(y):f0*Math.sqrt(y),gp=K,pk=gt(q,Math.SQRT1_2);
h+=row('Добротность Q = √(R1·R2·C1·C2)/'+(hp?'(R1·C1 + R1·C2 + R2·C2·(1 − K))':'(R1·C2 + R2·C2 + R1·C1·(1 − K))'),fmt(q,4)+(eq?' — при равных элементах 1/(3 − K)':''))+
 row('Усиление на частоте f0: K·Q',fmt(K*q,4)+' — '+fmt(db(K*q),4)+' дБ')+
 row('Частота среза по уровню −3 дБ от K',sp(f3,'Гц'));
if(pk){var z=1-1/(2*q*q),fp;gp=K*q/Math.sqrt(1-1/(4*q*q));fp=hp?f0/Math.sqrt(z):f0*Math.sqrt(z);
 h+=row('Подъём АЧХ над K',fmt(db(gp/K),4)+' дБ: наибольшее усиление '+fmt(gp,4)+' на частоте '+sp(fp,'Гц'));}
else h+=row('Подъём АЧХ над K','нет: Q не больше 1/√2 ≈ 0,7071');
var risk=[],miss=[];
if(tr===null||tc===null)miss.push('допуски резисторов и конденсаторов');
else{var ft=tr/100,fc=tc/100,lo=[R1*(1-ft),R2*(1-ft),C1*(1-fc),C2*(1-fc)],hi=[R1*(1+ft),R2*(1+ft),C1*(1+fc),C2*(1+fc)];
 var Kl=rb>0?1+rb*(1-ft)/(ra*(1+ft)):1,Kh=rb>0?1+rb*(1+ft)/(ra*(1-ft)):1,qn=Infinity,qx=0,fn=Infinity,fh=0,un=false,j;
 // 32 угла: R1, R2, C1, C2 и K на краях допусков. Q вдоль одного элемента ∝ √x/(β + γ·x) —
 // внутренний максимум при x = β/γ, если β, γ > 0; минимум Q и d — в углах (d линеен по каждому элементу).
 for(var k=0;k<32;k++){var y0=[];for(j=0;j<4;j++)y0.push((k>>j)&1?hi[j]:lo[j]);var KK=(k&16)?Kh:Kl,r0=qv(hp,y0,KK);
  var ff=1/(2*Math.PI*Math.sqrt(y0[0]*y0[1]*y0[2]*y0[3]));fn=Math.min(fn,ff);fh=Math.max(fh,ff);
  if(!(r0.d>0)){un=true;continue;}qn=Math.min(qn,r0.q);qx=Math.max(qx,r0.q);
  for(j=0;j<4;j++){var ya=y0.slice(),yb=y0.slice();ya[j]=lo[j];yb[j]=hi[j];var da=qv(hp,ya,KK).d,dd=qv(hp,yb,KK).d,gm=(dd-da)/(hi[j]-lo[j]),bt=da-gm*lo[j];
   if(bt>0&&gm>0){var xs=bt/gm;if(xs>lo[j]&&xs<hi[j]){ya[j]=xs;var rs=qv(hp,ya,KK);if(rs.d>0)qx=Math.max(qx,rs.q);}}}}
 h+=row('f0 при допусках ±'+fmt(tr)+' % и ±'+fmt(tc)+' %',sp(fn,'Гц')+' … '+sp(fh,'Гц'));
 if(un){h+=row('Q при допусках','не ограничена: в части сочетаний K достигает порога');risk.push('при допусках ±'+fmt(tr)+' % и ±'+fmt(tc)+' % в части сочетаний K достигает порога самовозбуждения');}
 else h+=row('Q при допусках',fmt(qn,4)+' … '+fmt(qx,4));}
// Правило TI (SBOA226, SBOA225): GBW ≥ 100·K·f, SR ≥ 2π·f·Vпик; f — для ФНЧ большая из f0 и частоты −3 дБ,
// для ФВЧ — наибольшая частота сигнала; амплитуда на выходе — с подъёмом АЧХ (Gмакс = наибольшее из K и пика).
var fr=hp?fm:Math.max(f0,f3);
if(gb===null)miss.push('GBW ОУ');
if(sr===null||vin===null)miss.push('скорость нарастания ОУ и амплитуда сигнала');
if(fr===null){if(gb!==null||sr!==null)miss.push('наибольшая частота сигнала');}
else{if(gb!==null){var gr=100*K*fr;h+=row('GBW по правилу TI: не меньше 100·K·f',sp(gr,'Гц')+' при f = '+sp(fr,'Гц')+'; GBW ОУ '+sp(gb,'Гц'));
  if(lt(gb,gr))risk.push('GBW ОУ '+sx(gb,gr,'Гц')+' меньше 100·K·f = '+sx(gr,gb,'Гц')+' по правилу TI — частота и добротность отклонятся от расчёта');}
 if(sr!==null&&vin!==null){var sq=2*Math.PI*fr*Math.max(K,gp)*vin/1e6;h+=row('Скорость нарастания по правилу TI: не меньше 2π·f·Gмакс·Vвх',fmt(sq,4)+' В/мкс; SR ОУ '+fmt(sr,4)+' В/мкс');
  if(lt(sr,sq))risk.push('скорость нарастания ОУ '+fx(sr,sq)+' В/мкс меньше '+fx(sq,sr)+' В/мкс — выходной синус исказится');}}
var st;
if(risk.length)st='Риск: '+risk.join('; ');
else if(miss.length)st='Недостаточно данных: не заданы '+miss.join(', ')+'; по номиналам f0 = '+sp(f0,'Гц')+', Q = '+fmt(q,4);
else st='Оценка: f0 = '+sp(f0,'Гц')+', Q = '+fmt(q,4)+'; в наихудшем сочетании допусков K ниже порога, GBW и скорость нарастания ОУ не меньше требуемых по правилу TI';
n+='Требования к ОУ — правило из примеров TI (SBOA226, SBOA225): GBW не меньше 100·K·f и скорость нарастания не меньше 2π·f·Vпик; f — большая из f0 и частоты −3 дБ для ФНЧ и наибольшая частота сигнала для ФВЧ, амплитуда на выходе — с подъёмом АЧХ. Это оценка: конечная полоса ОУ сдвигает частоту и повышает добротность (ADI MT-222). ';
n+='Разброс f0 и Q — перебор 32 сочетаний крайних значений элементов и усиления с поиском внутреннего максимума Q вдоль каждого элемента.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">ФНЧ: H(s) = K / [s²·R1R2C1C2 + s·(R1C2 + R2C2 + R1C1·(1 − K)) + 1]<br>ФВЧ: H(s) = K·s²·R1R2C1C2 / [s²·R1R2C1C2 + s·(R1C1 + R1C2 + R2C2·(1 − K)) + 1]<br>ω0 = 2π·f0 = 1/√(R1R2C1C2),&nbsp;&nbsp;Q = √(R1R2C1C2) / (коэффициент при s),&nbsp;&nbsp;K = 1 + Rb/Ra<br>самовозбуждение, если коэффициент при s ≤ 0: ФНЧ — K ≥ 1 + C2·(R1 + R2)/(R1·C1), ФВЧ — K ≥ 1 + R1·(C1 + C2)/(R2·C2)<br>равные элементы: Q = 1/(3 − K), порог K = 3;&nbsp;&nbsp;на f0 усиление K·Q<br>−3 дБ от K: x² = [2 − 1/Q² + √((2 − 1/Q²)² + 4)]/2, ФНЧ f = f0·x, ФВЧ f = f0/x<br>Баттерворт, K = 1: ФНЧ R1 = R2 = 1/(2π·f0·C·√2), C1 = 2·C, C2 = C; ФВЧ C1 = C2 = C, R1 = 1/(2π·f0·C·√2), R2 = 2·R1<br>Баттерворт, равные элементы: R = 1/(2π·f0·C), K = 3 − √2 ≈ 1,586, Rb = (2 − √2)·Ra</div>
<p><b>Схема и обозначения.</b> ФНЧ: вход → R1 → средняя точка → R2 → неинвертирующий вход ОУ; C1 — от средней точки на выход ОУ, это положительная обратная связь, C2 — от неинвертирующего входа на общий провод. ФВЧ: те же места, но резисторы и конденсаторы поменялись: вход → C1 → средняя точка → C2 → вход ОУ, R1 — от средней точки на выход, R2 — от входа ОУ на общий провод. ОУ включён неинвертирующим усилителем с K = 1 + Rb/Ra; при Rb = 0 это повторитель. Обозначения в документах изготовителей бывают другими — сверяйте по месту элемента в схеме.</p>
<p><b>Вывод из узловых уравнений.</b> Для ФНЧ по правилу узлов в средней точке A и на входе ОУ B — сопротивление конденсатора 1/(s·C): (Vвх − VA)/R1 + (VB − VA)/R2 + (Vвых − VA)·s·C1 = 0 и (VA − VB)/R2 = VB·s·C2, а Vвых = K·VB. Из второго уравнения VA = VB·(1 + s·R2·C2); подстановка в первое и умножение на R1 дают Vвх = VB·[s²·R1R2C1C2 + s·(R1C2 + R2C2 + R1C1·(1 − K)) + 1] — это знаменатель в рамке. Для ФВЧ так же, только проводимости s·C1 и s·C2 стоят в продольных ветвях, а 1/R1 и 1/R2 — в поперечных. Сравнение знаменателя со стандартной записью s²/ω0² + s/(ω0·Q) + 1 даёт ω0 и Q. TI в SLOA024B (J. Karki) разбирает ту же схему для ФНЧ и ФВЧ и для равных элементов получает Q = 1/(3 − K); формулы страницы выведены здесь и от пересказа этого документа не зависят.</p>
<p><b>Устойчивость.</b> Конденсатор C1 у ФНЧ или резистор R1 у ФВЧ подаёт с выхода положительную обратную связь, и с ростом K коэффициент при s уменьшается. Пока он положителен, полюса в левой полуплоскости. При нуле добротность бесконечна, полюса на мнимой оси — схема генерирует; при большем K полюса уходят в правую полуплоскость. Для равных элементов порог — K = 3, Q = 1/(3 − K). Калькулятор сравнивает K с порогом без округления через него. Чем ближе K к порогу, тем сильнее Q зависит от разброса элементов — ADI (MT-222) отмечает чувствительность схемы Саллена–Ки к значениям элементов, особенно при высокой добротности. Поэтому при заданных допусках калькулятор перебирает все 32 сочетания крайних значений R1, R2, C1, C2 и усиления и ищет внутренний максимум добротности вдоль каждого элемента: Q ∝ √x/(β + γ·x) имеет максимум при x = β/γ. Коэффициент при s линеен по каждому элементу, поэтому его наименьшее значение и наименьшая добротность лежат в углах; f0 монотонна по каждому элементу, и её крайние значения тоже в углах.</p>
<p><b>Частота среза, подъём и синтез.</b> На f0 усиление равно K·Q. Частота −3 дБ от K совпадает с f0 только у фильтра Баттерворта, Q = 1/√2 ≈ 0,7071; при большей добротности у АЧХ появляется подъём — до K·Q/√(1 − 1/(4·Q²)). Режим синтеза рассчитывает фильтр Баттерворта двумя распространёнными способами: при единичном усилении (ФНЧ — равные резисторы и C1 = 2·C2, ФВЧ — равные конденсаторы и R2 = 2·R1) и при равных элементах с K = 3 − √2. Полученные номиналы проходят тот же анализ, что и введённые вручную.</p>
<p><b>Требования к ОУ.</b> Формулы выше — для идеального ОУ. Конечная полоса ОУ сдвигает частоту и повышает добротность. TI в примерах SBOA226 (ФНЧ) и SBOA225 (ФВЧ) берёт GBW не меньше 100·K·f и скорость нарастания не меньше 2π·f·Vпик: для ФНЧ f — частота среза, для ФВЧ — наибольшая частота сигнала, ведь ФВЧ пропускает всё выше f0. Калькулятор берёт для ФНЧ большую из f0 и частоты −3 дБ, а в скорости нарастания учитывает амплитуду на выходе с подъёмом АЧХ. Это правило оценки, поэтому его невыполнение — «Риск», а без GBW и скорости нарастания — «Недостаточно данных», хотя сам фильтр рассчитан.</p>
<p><b>Чем отличается от соседних страниц.</b> <a href="rc-filtr.html">RC-фильтр</a> — первого порядка: спад 6 дБ на октаву и нет добротности. <a href="lc-filtr-raschet.html">Пассивный LC-фильтр</a> второго порядка работает на нагрузку без ОУ, а его добротность задают L, C и сопротивление нагрузки. Фильтр Саллена–Ки даёт второй порядок, 12 дБ на октаву, без катушек: добротность задают соотношения элементов и усиление ОУ, включённого <a href="ou-usilenie.html">неинвертирующим усилителем</a>. Уровни в децибелах переводит <a href="decibel.html">калькулятор децибел</a>.</p>""",
example="""<p>ФНЧ с повторителем, R1 = R2 = 10 кОм, C1 = 22 нФ, C2 = 10 нФ: f0 = 1/(2π·√(10⁴·10⁴·22·10⁻⁹·10⁻⁸)) = <b>1073 Гц</b>, Q = √(2,2)/2 = <b>0,7416</b> — чуть выше Баттерворта, поэтому срез −3 дБ на 1123 Гц, а у АЧХ подъём 0,036 дБ около 323,5 Гц. Порог самовозбуждения Kпред = 1 + 10·20/(10·22) = 1,909, при K = 1 запас большой.</p>
<p>Синтез Баттерворта на 1 кГц с C = 10 нФ: при единичном усилении R1 = R2 = 11,25 кОм, C1 = 20 нФ; при равных элементах R = 15,92 кОм и K = 1,586, то есть Rb = 5,858 кОм при Ra = 10 кОм. Если в схеме с равными элементами поднять K до 2,9, добротность станет 10, а при K = 3 фильтр самовозбуждается.</p>
<p>Для ФНЧ из первого примера правило TI требует GBW не меньше 100·1·1123 Гц = 112,3 кГц. Значения условные; GBW и скорость нарастания введите из паспорта своего ОУ.</p>""",
